css:
.cba-sim-container {
    padding: 28px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}
.cba-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #2c3e6b 100%);
    color: #ffffff;
    padding: 36px 32px 28px;
    border-radius: 4px;
    margin-bottom: 24px;
    border-bottom: 4px solid #c9a84c;
}
.cba-sim-header-badge {
    display: inline-block;
    background: rgba(201,168,76,0.2);
    color: #c9a84c;
    font-size: 0.7rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    padding: 4px 12px;
    border-radius: 2px;
    border: 1px solid rgba(201,168,76,0.4);
    margin-bottom: 12px;
}
.cba-sim-header h1 {
    font-size: 1.5rem;
    font-weight: 700;
    margin: 0 0 6px 0;
    letter-spacing: -0.01em;
}
.cba-sim-subtitle {
    font-size: 0.9rem;
    color: rgba(255,255,255,0.7);
    margin: 0;
}
.cba-sim-period-counter {
    text-align: center;
    font-size: 0.85rem;
    color: #5a6a7e;
    margin-bottom: 20px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.cba-sim-period-counter span {
    margin: 0 3px;
}
.cba-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 24px;
}
.cba-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #dde1e7;
    border-radius: 4px;
    padding: 20px 16px;
    text-align: center;
    border-top: 3px solid #1a2744;
}
.cba-sim-kpi-label {
    color: #5a6a7e;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
    font-weight: 600;
}
.cba-sim-kpi-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #1a2744;
}
.cba-sim-briefing {
    background: #ffffff;
    border: 1px solid #dde1e7;
    border-radius: 4px;
    padding: 28px;
    margin-bottom: 24px;
    border-left: 4px solid #c9a84c;
}
.cba-sim-briefing-tag {
    display: inline-block;
    background: #1a2744;
    color: #ffffff;
    font-size: 0.65rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    padding: 3px 10px;
    border-radius: 2px;
    margin-bottom: 12px;
}
.cba-sim-briefing h3 {
    font-size: 1.15rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 10px 0;
}
.cba-sim-briefing p {
    font-size: 0.88rem;
    color: #3a4a5e;
    line-height: 1.6;
    margin: 0 0 16px 0;
}
.cba-sim-briefing-data {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
}
.cba-sim-data-item {
    background: #f8f9fb;
    padding: 12px 14px;
    border-radius: 3px;
    border: 1px solid #eceef2;
}
.cba-sim-data-label {
    display: block;
    font-size: 0.65rem;
    color: #5a6a7e;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 4px;
    font-weight: 600;
}
.cba-sim-data-value {
    display: block;
    font-size: 1rem;
    font-weight: 700;
    color: #1a2744;
}
.cba-sim-controls {
    background: #ffffff;
    border: 1px solid #dde1e7;
    border-radius: 4px;
    padding: 28px;
    margin-bottom: 24px;
}
.cba-sim-controls h3 {
    font-size: 1rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 20px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #eceef2;
}
.cba-sim-controls-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
    margin-bottom: 24px;
}
.cba-sim-control-group label {
    display: block;
    font-size: 0.75rem;
    font-weight: 600;
    color: #3a4a5e;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 6px;
}
.cba-sim-controls input[type="number"] {
    background: #f8f9fb;
    border: 1px solid #cdd3dc;
    color: #1a2744;
    border-radius: 3px;
    padding: 10px 14px;
    width: 100%;
    font-size: 0.95rem;
    font-weight: 600;
    transition: border-color 0.2s ease;
}
.cba-sim-controls input[type="number"]:focus {
    border-color: #1a2744;
    outline: none;
    box-shadow: 0 0 0 2px rgba(26,39,68,0.12);
}
.cba-sim-controls select {
    background: #f8f9fb;
    border: 1px solid #cdd3dc;
    color: #1a2744;
    border-radius: 3px;
    padding: 10px 14px;
    width: 100%;
    font-size: 0.88rem;
    font-weight: 500;
    cursor: pointer;
    transition: border-color 0.2s ease;
}
.cba-sim-controls select:focus {
    border-color: #1a2744;
    outline: none;
    box-shadow: 0 0 0 2px rgba(26,39,68,0.12);
}
.cba-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
}
.cba-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
}
.cba-sim-submit-btn {
    background: #1a2744;
    border: none;
    color: #ffffff;
    padding: 12px 32px;
    font-size: 0.9rem;
    font-weight: 600;
    border-radius: 3px;
    cursor: pointer;
    transition: background 0.2s ease;
}
.cba-sim-submit-btn:hover {
    background: #2c3e6b;
}
.cba-sim-history {
    background: #ffffff;
    border: 1px solid #dde1e7;
    border-radius: 4px;
    padding: 20px;
    margin-bottom: 24px;
    overflow-x: auto;
}
.cba-sim-history table {
    font-size: 0.82rem;
    margin: 0;
}
.cba-sim-history th {
    background: #1a2744;
    color: #ffffff;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 600;
    padding: 10px 12px;
    border: none;
}
.cba-sim-history td {
    padding: 8px 12px;
    vertical-align: middle;
    color: #3a4a5e;
    border-color: #eceef2;
}
.cba-sim-chart-section {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
    margin-bottom: 24px;
}
.cba-sim-chart-box {
    background: #ffffff;
    border: 1px solid #dde1e7;
    border-radius: 4px;
    padding: 20px;
    min-height: 280px;
}
@media (max-width: 768px) {
    .cba-sim-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
    }
    .cba-sim-controls-grid {
        grid-template-columns: 1fr;
    }
    .cba-sim-briefing-data {
        grid-template-columns: 1fr;
    }
    .cba-sim-chart-section {
        grid-template-columns: 1fr;
    }
    .cba-sim-header h1 {
        font-size: 1.2rem;
    }
}

js:
(function() {
    'use strict';

    class CBAAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'CBA Políticas Públicas';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    title: 'Autopista 4G Ruta del Sol — Tramo III',
                    sector: 'Infraestructura Vial',
                    description: 'El Gobierno Nacional propone construir 190 km de autopista de cuarta generación conectando el centro del país con la costa Caribe. El proyecto incluye 12 puentes, 3 túneles y mejoramiento de 45 km existentes. Se espera reducir tiempos de viaje en un 40% y disminuir la siniestralidad vial. Sin embargo, existen preocupaciones por el desplazamiento de comunidades rurales y el impacto ambiental en zonas de humedal.',
                    baseCost: 2500000,
                    annualBenefit: 420000,
                    optimalRate: 6,
                    horizon: 25,
                    costFactors: { conservative: 1.25, moderate: 1.0, aggressive: 0.85 },
                    benefitFactors: { direct: 0.55, indirect: 0.80, externalities: 1.0 },
                    optimalScope: 'externalities',
                    optimalRecommendation: 'approve'
                },
                {
                    title: 'Programa Nacional de Vacunación Ampliada',
                    sector: 'Salud Pública',
                    description: 'El Ministerio de Salud plantea ampliar el Programa Ampliado de Inmunización (PAI) para cubrir 4 nuevas vacunas, con meta de cobertura del 95% en municipios PDET. El programa requiere inversión en cadena de frío, capacitación de 8.000 vacunadores y campañas en zonas dispersas. Los beneficios incluyen reducción de mortalidad infantil, menos hospitalizaciones y mayor productividad laboral a largo plazo.',
                    baseCost: 850000,
                    annualBenefit: 280000,
                    optimalRate: 4,
                    horizon: 30,
                    costFactors: { conservative: 1.20, moderate: 1.0, aggressive: 0.90 },
                    benefitFactors: { direct: 0.45, indirect: 0.75, externalities: 1.0 },
                    optimalScope: 'externalities',
                    optimalRecommendation: 'approve'
                },
                {
                    title: 'Modernización Tecnológica de Educación Rural',
                    sector: 'Educación',
                    description: 'El Ministerio de Educación propone dotar de conectividad satelital y tabletas a 6.200 sedes educativas rurales en 28 departamentos. El proyecto incluye formación docente en competencias digitales y desarrollo de contenidos pedagógicos contextualizados. Los costos de mantenimiento y actualización tecnológica representan un reto significativo. Los beneficios directos se verán reflejados en mejores resultados en pruebas Saber y reducción de la brecha digital.',
                    baseCost: 1200000,
                    annualBenefit: 155000,
                    optimalRate: 5,
                    horizon: 20,
                    costFactors: { conservative: 1.30, moderate: 1.0, aggressive: 0.80 },
                    benefitFactors: { direct: 0.50, indirect: 0.78, externalities: 1.0 },
                    optimalScope: 'indirect',
                    optimalRecommendation: 'modify'
                },
                {
                    title: 'Restauración Ambiental del Río Bogotá',
                    sector: 'Medio Ambiente',
                    description: 'La CAR y el Distrito Capital proponen un plan integral de descontaminación del río Bogotá en su cuenca media y baja. El proyecto incluye ampliación de la PTAR Salitre, construcción de colectores de aguas residuales en 12 municipios, y restauración de 3.500 hectáreas de ronda hídrica. Los beneficios abarcan mejora en salud pública, valorización de predios, recuperación de ecosistemas y cumplimiento del fallo del Consejo de Estado. La inversión es considerable pero el costo de la inacción supera ampliamente el costo del proyecto.',
                    baseCost: 3200000,
                    annualBenefit: 380000,
                    optimalRate: 3.5,
                    horizon: 35,
                    costFactors: { conservative: 1.20, moderate: 1.0, aggressive: 0.85 },
                    benefitFactors: { direct: 0.40, indirect: 0.70, externalities: 1.0 },
                    optimalScope: 'externalities',
                    optimalRecommendation: 'approve'
                }
            ];

            // English translations of the round dossiers (the ROUNDS content above is the
            // Spanish source). Rendered by _updateBriefing/calculateResults when the session
            // language is English, so the sim's declared EN mode shows English content — not
            // English chrome over Spanish dossiers/units. (v1.1.0)
            this.EN = [
                { title: 'Ruta del Sol 4G Highway — Section III', sector: 'Road Infrastructure', description: 'The National Government proposes building 190 km of fourth-generation (4G) highway connecting the center of the country with the Caribbean coast. The project includes 12 bridges, 3 tunnels, and upgrades to 45 existing km. It is expected to cut travel times by 40% and reduce road accidents. However, there are concerns about the displacement of rural communities and the environmental impact on wetland areas.' },
                { title: 'Expanded National Vaccination Program', sector: 'Public Health', description: 'The Ministry of Health proposes expanding the Expanded Immunization Program (PAI) to cover 4 new vaccines, targeting 95% coverage in PDET municipalities. The program requires investment in the cold chain, training for 8,000 vaccinators, and outreach campaigns in remote areas. Benefits include lower infant mortality, fewer hospitalizations, and higher long-term labor productivity.' },
                { title: 'Technological Modernization of Rural Education', sector: 'Education', description: 'The Ministry of Education proposes providing satellite connectivity and tablets to 6,200 rural schools across 28 departments. The project includes teacher training in digital skills and the development of context-specific educational content. Technology maintenance and upgrade costs are a significant challenge. Direct benefits will show in better Saber test results and a narrower digital divide.' },
                { title: 'Environmental Restoration of the Bogotá River', sector: 'Environment', description: 'The CAR and the Capital District propose a comprehensive decontamination plan for the middle and lower basin of the Bogotá River. It includes expanding the Salitre wastewater treatment plant (PTAR), building sewage collectors in 12 municipalities, and restoring 3,500 hectares of riverbank. Benefits span better public health, property-value gains, ecosystem recovery, and compliance with the Council of State ruling. The investment is large, but the cost of inaction far exceeds it.' }
            ];
        }

        _lang() {
            var sim = window.mySimulation;
            var raw = (sim && sim.language) || (sim && sim.currentLanguage) || document.documentElement.lang || 'en';
            return (raw && raw.toString().toLowerCase().indexOf('es') === 0) ? 'es' : 'en';
        }

        initialize(state) {
            // Reset domainState on a fresh start OR when there is no completed-round history
            // (the framework calls initialize() after Undo pops the last row to empty). The old
            // guard only checked for an empty domainState, so undo-to-start left the counted
            // totals in place and the next submit double-counted them. (v1.1.0 fix)
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    reputation: 50,
                    projectsEvaluated: 0,
                    totalScore: 0,
                    bcrHistory: [],
                    npvHistory: [],
                    reputationHistory: [],
                    scoreHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    discountRate: 6,
                    costApproach: 'moderate',
                    benefitScope: 'indirect',
                    recommendation: 'approve'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);

            var rateInput = document.getElementById('discountRateInput');
            if (rateInput) decisions.discountRate = parseFloat(rateInput.value);

            var costSelect = document.getElementById('costApproachSelect');
            if (costSelect) decisions.costApproach = costSelect.value;

            var scopeSelect = document.getElementById('benefitScopeSelect');
            if (scopeSelect) decisions.benefitScope = scopeSelect.value;

            var recSelect = document.getElementById('recommendationSelect');
            if (recSelect) decisions.recommendation = recSelect.value;

            if (!decisions.discountRate || decisions.discountRate < 1 || decisions.discountRate > 15) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('rate_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var rate = d.discountRate / 100;
            var costFactor = round.costFactors[d.costApproach] || 1.0;
            var benefitFactor = round.benefitFactors[d.benefitScope] || 0.8;

            var totalCost = round.baseCost * costFactor;
            var annualBen = round.annualBenefit * benefitFactor;

            var pvFactor = (1 - Math.pow(1 + rate, -round.horizon)) / rate;
            var pvBenefits = annualBen * pvFactor;
            var npv = pvBenefits - totalCost;
            var bcr = pvBenefits / totalCost;

            var score = 0;
            var maxScore = 100;

            var rateDiff = Math.abs(d.discountRate - round.optimalRate);
            if (rateDiff <= 0.5) score += 30;
            else if (rateDiff <= 1.5) score += 22;
            else if (rateDiff <= 3) score += 12;
            else score += 0;

            if (d.benefitScope === round.optimalScope) score += 30;
            else if (d.benefitScope === 'indirect' && round.optimalScope === 'externalities') score += 18;
            else if (d.benefitScope === 'externalities' && round.optimalScope === 'indirect') score += 18;
            else score += 5;

            var correctRec = round.optimalRecommendation;
            if (d.recommendation === correctRec) score += 25;
            else if ((d.recommendation === 'modify' && correctRec === 'approve') ||
                     (d.recommendation === 'approve' && correctRec === 'modify')) score += 12;
            else score += 0;

            if (d.costApproach === 'conservative') score += 15;
            else if (d.costApproach === 'moderate') score += 10;
            else score += 3;

            score = Math.min(score, maxScore);

            var repChange = Math.round((score - 50) * 0.4);
            state.domainState.reputation = Math.max(0, Math.min(100, state.domainState.reputation + repChange));
            state.domainState.projectsEvaluated += 1;
            state.domainState.totalScore += score;

            state.domainState.bcrHistory.push(Math.round(bcr * 100) / 100);
            state.domainState.npvHistory.push(Math.round(npv));
            state.domainState.reputationHistory.push(state.domainState.reputation);
            state.domainState.scoreHistory.push(score);

            var self = this;
            // Render the NEXT round's dossier. Use the captured `period` (the round just
            // graded): the framework increments state.currentPeriod synchronously after
            // calculateResults returns, so by the time this 500ms timeout fired, reading
            // state.currentPeriod + 1 pointed TWO rounds ahead — the analyst evaluated the
            // wrong project on rounds 2-3. Guard the final round. (v1.1.0 fix)
            var maxP = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.maxPeriods) || this.ROUNDS.length;
            if (period < maxP) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: period + 1 });
                }, 500);
            }

            return {
                period: state.currentPeriod,
                project: (this._lang() === 'en' && this.EN[idx]) ? this.EN[idx].title : round.title,
                discountRate: d.discountRate,
                costApproach: d.costApproach,
                benefitScope: d.benefitScope,
                recommendation: d.recommendation,
                totalCost: Math.round(totalCost),
                pvBenefits: Math.round(pvBenefits),
                npv: Math.round(npv),
                bcr: Math.round(bcr * 100) / 100,
                score: score,
                reputation: state.domainState.reputation
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('reputationDisplay', 'domainState.reputation',
                (v) => v + '/100');
            uiManager.bind('projectsDisplay', 'domainState.projectsEvaluated');
            uiManager.bind('bcrDisplay', 'results.bcr',
                (v) => v ? v.toFixed(2) : '—');
            uiManager.bind('npvDisplay', 'results.npv',
                (v) => v !== undefined ? '$' + Math.round(v / 1000).toLocaleString() + ' MM' : '—');
        }

        getChartConfig() {
            return {
                bcrChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'BCR',
                            data: [],
                            backgroundColor: ['rgba(26,39,68,0.75)', 'rgba(44,62,107,0.75)', 'rgba(201,168,76,0.75)', 'rgba(90,106,126,0.75)'],
                            borderColor: ['#1a2744', '#2c3e6b', '#c9a84c', '#5a6a7e'],
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Razón Beneficio-Costo por Proyecto', font: { size: 13, weight: '600' }, color: '#1a2744' },
                            legend: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                title: { display: true, text: 'BCR', color: '#5a6a7e', font: { size: 11 } },
                                grid: { color: 'rgba(0,0,0,0.06)' }
                            },
                            x: { grid: { display: false } }
                        }
                    }
                },
                reputationChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Reputación',
                            data: [],
                            borderColor: '#c9a84c',
                            backgroundColor: 'rgba(201,168,76,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3,
                            pointBackgroundColor: '#1a2744',
                            pointRadius: 5
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Evolución de Reputación Analítica', font: { size: 13, weight: '600' }, color: '#1a2744' },
                            legend: { display: false }
                        },
                        scales: {
                            y: {
                                min: 0, max: 100,
                                title: { display: true, text: 'Puntuación', color: '#5a6a7e', font: { size: 11 } },
                                grid: { color: 'rgba(0,0,0,0.06)' }
                            },
                            x: { grid: { display: false } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var projectLabels = [];
            for (var i = 0; i < state.domainState.bcrHistory.length; i++) {
                var rIdx = Math.min(i, this.ROUNDS.length - 1);
                projectLabels.push('R' + (i + 1));
            }
            return {
                bcrChart: {
                    labels: projectLabels,
                    datasets: [{ data: state.domainState.bcrHistory }]
                },
                reputationChart: {
                    labels: projectLabels,
                    datasets: [{ data: state.domainState.reputationHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.score || 0 : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var avgScore = totalScore / scores.length;
            var bcrs = history.map(function(r) { return r.results ? r.results.bcr || 0 : 0; });
            var avgBcr = bcrs.reduce(function(s, v) { return s + v; }, 0) / bcrs.length;

            var t = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var performance = t('tier_junior');
            if (avgScore >= 80) performance = t('tier_experto');
            else if (avgScore >= 60) performance = t('tier_senior');
            else if (avgScore >= 40) performance = t('tier_intermedio');

            var insights = [];
            if (avgScore >= 75) insights.push(t('insight_high'));
            else if (avgScore >= 50) insights.push(t('insight_mid'));
            else insights.push(t('insight_low'));

            return {
                totalScore: totalScore,
                avgScore: Math.round(avgScore),
                avgBcr: Math.round(avgBcr * 100) / 100,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.bcr < 1.0) return window.mySimulation.t('hint_bcr_low');
            if (results.score < 40) return window.mySimulation.t('hint_low_score');
            if (results.score >= 80) return window.mySimulation.t('hint_excellent');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.project', label: 'Proyecto', i18nKey: 'col_project' },
                { key: 'decisions.discountRate', label: 'Tasa %', i18nKey: 'col_rate', formatter: function(v) { return v + '%'; } },
